def search_semantic_scholar(query, num_results=None, **_extra):
    import json, os, datetime, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0020000" if __import__("os").path.isdir("./environment_mix/0020000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # No auth material in signature: treat as already authenticated.
    # No explicit rate/quota collections provided in schema: nothing to enforce/log.

    # Validate inputs
    if not isinstance(query, str) or query.strip() == "":
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    if num_results is None:
        num_results = 10
    if not isinstance(num_results, int):
        return _err("VALIDATION_ERROR", "num_results must be an integer")
    if not (1 <= num_results <= 100):
        return _err("VALIDATION_ERROR", "num_results must be between 1 and 100")

    search_queries = _load("search_queries.json")
    search_results = _load("search_results.json")
    papers = _load("papers.json")

    def _new_id(prefix, entropy):
        h = hashlib.sha256(entropy.encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{h}"

    def _find_paper(pid):
        for p in papers:
            if p.get("id") == pid:
                return p
        return None

    def _normalize_int_year(y):
        if y is None:
            return None
        if isinstance(y, bool):
            return None
        if isinstance(y, int):
            return y if 1800 <= y <= 2100 else None
        try:
            yi = int(y)
            return yi if 1800 <= yi <= 2100 else None
        except Exception:
            return None

    def _normalize_nonneg_int(x):
        if x is None:
            return None
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x if x >= 0 else None
        try:
            xi = int(x)
            return xi if xi >= 0 else None
        except Exception:
            return None

    def _ensure_unique_doi_constraint(pid, doi_value):
        if doi_value is None:
            return True
        for p in papers:
            if p.get("id") != pid and p.get("doi") is not None and p.get("doi") == doi_value:
                return False
        return True

    # Create search query row queued -> running -> succeeded/failed
    entropy = f"{query.strip()}|{num_results}|{now}|{random.random()}"
    sq_id = _new_id("sq", entropy)
    sq_row = {
        "id": sq_id,
        "query_text": query,
        "num_results_requested": num_results,
        "num_results_returned": None,
        "status": "queued",
        "error_message": None,
        "vendor_request_id": None,
        "vendor_latency_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    search_queries.append(sq_row)
    _save("search_queries.json", search_queries)

    # Transition queued -> running
    sq_row["status"] = "running"
    sq_row["updated_at"] = now
    _save("search_queries.json", search_queries)

    # Offline "upstream": search within cached papers by title/abstract/doi/id.
    # If too few cached matches, generate deterministic stub papers to fulfill request.
    try:
        q = query.strip().lower()

        def _text(p):
            return " ".join([
                str(p.get("id") or ""),
                str(p.get("title") or ""),
                str(p.get("abstract") or ""),
                str(p.get("doi") or ""),
                str(p.get("venue") or ""),
            ]).lower()

        scored = []
        for p in papers:
            if p.get("status") != "active":
                continue
            txt = _text(p)
            if q in txt:
                # simple score: occurrences of q plus title bonus
                occ = txt.count(q)
                bonus = 2 if (p.get("title") and q in (p.get("title") or "").lower()) else 0
                scored.append((occ + bonus, p))

        scored.sort(key=lambda t: (-t[0], str((t[1] or {}).get("id") or "")))
        hits = [p for _, p in scored][:num_results]

        # If not enough hits, synthesize stubs (but still "upsert papers for returned items").
        if len(hits) < num_results:
            need = num_results - len(hits)
            for i in range(need):
                stub_pid = _new_id("paper", f"{q}|{sq_id}|{i}")
                existing = _find_paper(stub_pid)
                if existing is None:
                    stub = {
                        "id": stub_pid,
                        "title": f"Stub paper for query: {query.strip()} (#{i+1})",
                        "abstract": None,
                        "year": None,
                        "venue": None,
                        "doi": None,
                        "url": None,
                        "fields_of_study": None,
                        "citation_count": None,
                        "reference_count": None,
                        "external_ids": None,
                        "status": "active",
                        "last_fetched_at": None,
                        "fetched_etag": None,
                        "created_at": now,
                        "updated_at": now,
                    }
                    papers.append(stub)
                    hits.append(stub)
                else:
                    # ensure active
                    existing["status"] = "active"
                    existing["updated_at"] = now
                    hits.append(existing)

        # Upsert papers for returned items; normalize constraints
        for p in hits:
            pid = p.get("id")
            if not isinstance(pid, str) or pid.strip() == "":
                raise ValueError("bad paper id in upstream result")
            row = _find_paper(pid)
            if row is None:
                # treat as new
                row = {
                    "id": pid,
                    "title": p.get("title") if isinstance(p.get("title"), str) else None,
                    "abstract": p.get("abstract") if isinstance(p.get("abstract"), str) else None,
                    "year": _normalize_int_year(p.get("year")),
                    "venue": p.get("venue") if isinstance(p.get("venue"), str) else None,
                    "doi": p.get("doi") if isinstance(p.get("doi"), str) and p.get("doi").strip() != "" else None,
                    "url": p.get("url") if isinstance(p.get("url"), str) else None,
                    "fields_of_study": p.get("fields_of_study") if isinstance(p.get("fields_of_study"), list) else None,
                    "citation_count": _normalize_nonneg_int(p.get("citation_count")),
                    "reference_count": _normalize_nonneg_int(p.get("reference_count")),
                    "external_ids": p.get("external_ids") if isinstance(p.get("external_ids"), dict) else None,
                    "status": "active",
                    "last_fetched_at": p.get("last_fetched_at") if isinstance(p.get("last_fetched_at"), str) else None,
                    "fetched_etag": p.get("fetched_etag") if isinstance(p.get("fetched_etag"), str) else None,
                    "created_at": now,
                    "updated_at": now,
                }
                if not _ensure_unique_doi_constraint(pid, row.get("doi")):
                    row["doi"] = None
                papers.append(row)
            else:
                # update selected fields if present; keep constraints
                if isinstance(p.get("title"), str):
                    row["title"] = p.get("title")
                if isinstance(p.get("abstract"), str):
                    row["abstract"] = p.get("abstract")
                row["year"] = _normalize_int_year(p.get("year", row.get("year")))
                if isinstance(p.get("venue"), str):
                    row["venue"] = p.get("venue")
                doi_candidate = p.get("doi")
                if isinstance(doi_candidate, str) and doi_candidate.strip() == "":
                    doi_candidate = None
                if doi_candidate is not None:
                    if _ensure_unique_doi_constraint(pid, doi_candidate):
                        row["doi"] = doi_candidate
                if isinstance(p.get("url"), str):
                    row["url"] = p.get("url")
                if isinstance(p.get("fields_of_study"), list):
                    row["fields_of_study"] = p.get("fields_of_study")
                if "citation_count" in p:
                    row["citation_count"] = _normalize_nonneg_int(p.get("citation_count"))
                if "reference_count" in p:
                    row["reference_count"] = _normalize_nonneg_int(p.get("reference_count"))
                if isinstance(p.get("external_ids"), dict):
                    row["external_ids"] = p.get("external_ids")
                row["status"] = "active"
                row["updated_at"] = now

        _save("papers.json", papers)

        # Insert search_results ranks 1..N without gaps, unique constraints
        # First, remove any accidental prior rows for this query id (should be none, but idempotence safety).
        search_results = [r for r in search_results if r.get("search_query_id") != sq_id]

        returned = min(len(hits), num_results)
        if returned < 0 or returned > num_results:
            raise ValueError("invalid returned count")
        for idx in range(returned):
            rank = idx + 1
            pid = hits[idx]["id"]
            # FK checks
            if _find_paper(pid) is None:
                raise ValueError("paper FK missing")
            # unique(search_query_id, rank) & unique(search_query_id, paper_id)
            for r in search_results:
                if r.get("search_query_id") == sq_id and r.get("rank") == rank:
                    raise ValueError("duplicate rank")
                if r.get("search_query_id") == sq_id and r.get("paper_id") == pid:
                    raise ValueError("duplicate paper in results")
            sr_id = _new_id("sr", f"{sq_id}|{rank}|{pid}")
            search_results.append({
                "id": sr_id,
                "search_query_id": sq_id,
                "rank": rank,
                "paper_id": pid,
                "score": None,
                "snippet": None,
                "created_at": now,
                "updated_at": now,
            })

        _save("search_results.json", search_results)

        # Transition running -> succeeded
        sq_row["status"] = "succeeded"
        sq_row["num_results_returned"] = returned
        sq_row["vendor_latency_ms"] = int((time.time() - t0) * 1000)
        sq_row["updated_at"] = now
        _save("search_queries.json", search_queries)

        # Return papers in rank order with metadata
        results_out = []
        for idx in range(returned):
            results_out.append(_find_paper(hits[idx]["id"]))
        return {
            "search_query": sq_row,
            "results": results_out,
            "meta": {
                "requested": num_results,
                "returned": returned,
                "search_query_id": sq_id,
            }
        }

    except ValueError as e:
        sq_row["status"] = "failed"
        sq_row["error_message"] = str(e)
        sq_row["vendor_latency_ms"] = int((time.time() - t0) * 1000)
        sq_row["updated_at"] = now
        _save("search_queries.json", search_queries)
        return _err("VALIDATION_ERROR", "search failed due to invalid data", detail=str(e), search_query_id=sq_id)
    except Exception as e:
        # Unexpected failures should not raise per requirements; return a failure row + error.
        sq_row["status"] = "failed"
        sq_row["error_message"] = "internal error"
        sq_row["vendor_latency_ms"] = int((time.time() - t0) * 1000)
        sq_row["updated_at"] = now
        _save("search_queries.json", search_queries)
        return _err("CONFLICT", "internal error", detail=str(e), search_query_id=sq_id)

def get_semantic_scholar_paper_details(paper_id, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0020000" if __import__("os").path.isdir("./environment_mix/0020000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    if not isinstance(paper_id, str) or paper_id.strip() == "":
        return _err("VALIDATION_ERROR", "paper_id must be a non-empty string")

    papers = _load("papers.json")

    def _parse_dt(s):
        if not isinstance(s, str) or s.strip() == "":
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _normalize_int_year(y):
        if y is None:
            return None
        if isinstance(y, bool):
            return None
        if isinstance(y, int):
            return y if 1800 <= y <= 2100 else None
        try:
            yi = int(y)
            return yi if 1800 <= yi <= 2100 else None
        except Exception:
            return None

    def _normalize_nonneg_int(x):
        if x is None:
            return None
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x if x >= 0 else None
        try:
            xi = int(x)
            return xi if xi >= 0 else None
        except Exception:
            return None

    def _ensure_unique_doi_constraint(pid, doi_value):
        if doi_value is None:
            return True
        for p in papers:
            if p.get("id") != pid and p.get("doi") is not None and p.get("doi") == doi_value:
                return False
        return True

    def _find():
        for p in papers:
            if p.get("id") == paper_id:
                return p
        return None

    # Configured TTL (offline server default)
    TTL_SECONDS = 7 * 24 * 3600

    row = _find()
    stale = True
    if row is not None:
        lf = _parse_dt(row.get("last_fetched_at"))
        if lf is not None and (now_dt - lf).total_seconds() <= TTL_SECONDS:
            stale = False

    if row is not None and not stale:
        return {"paper": row, "meta": {"source": "cache", "stale": False}}

    # Offline "upstream fetch": if paper exists in cache, refresh fields deterministically;
    # if not present, treat as NOT_FOUND (as required).
    if row is None:
        return _err("NOT_FOUND", "paper not found in Semantic Scholar", paper_id=paper_id)

    # Refresh/upsert
    try:
        # Deterministic enrichment based on id
        h = hashlib.sha256(paper_id.encode("utf-8")).hexdigest()
        year = 1800 + (int(h[:4], 16) % 301)  # 1800..2100
        row["title"] = row.get("title") or f"Paper {paper_id}"
        if row.get("abstract") is None:
            row["abstract"] = f"Abstract for {paper_id} (cached/offline refresh)."
        row["year"] = _normalize_int_year(row.get("year") if row.get("year") is not None else year)
        row["venue"] = row.get("venue") or "Unknown Venue"
        doi_candidate = row.get("doi")
        if isinstance(doi_candidate, str) and doi_candidate.strip() == "":
            doi_candidate = None
        if doi_candidate is not None and not _ensure_unique_doi_constraint(paper_id, doi_candidate):
            row["doi"] = None
        row["citation_count"] = _normalize_nonneg_int(row.get("citation_count"))
        row["reference_count"] = _normalize_nonneg_int(row.get("reference_count"))
        if row.get("status") not in ("active", "tombstoned"):
            row["status"] = "active"
        row["status"] = "active"
        row["last_fetched_at"] = now
        row["updated_at"] = now
        _save("papers.json", papers)
        return {"paper": row, "meta": {"source": "refreshed", "stale": True}}
    except Exception as e:
        return _err("CONFLICT", "internal error", detail=str(e))

def get_semantic_scholar_author_details(author_id, **_extra):
    import json, os, datetime, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0020000" if __import__("os").path.isdir("./environment_mix/0020000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    now_dt = t0.replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    # ---- validation ----
    if not isinstance(author_id, str) or author_id.strip() == "":
        return _err("VALIDATION_ERROR", "author_id must be a non-empty string.", author_id=author_id)
    author_id = author_id.strip()

    # ---- ambient auth (no explicit credentials in tool signature) ----
    if not os.path.isdir(_DB):
        return _err("UNAUTHORIZED", "Caller is not permitted to access the backend.")

    # ---- request logging (observable dynamics) ----
    log_file = "request_logs.json"
    logs = _load(log_file)
    if not isinstance(logs, list):
        logs = []
    req_id = f"req_{now_dt.strftime('%Y%m%d%H%M%S')}_{os.urandom(6).hex()}"
    logs.append({
        "id": req_id,
        "service": "semantic_scholar",
        "endpoint": "get_semantic_scholar_author_details",
        "timestamp": now_iso,
        "status": "running",
        "latency_ms": None,
        "credential": None,
        "author_id": author_id,
    })
    _save(log_file, logs)

    def _finalize(ok, error_code=None, http_status=None):
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        cur = _load(log_file)
        if not isinstance(cur, list):
            return
        for r in reversed(cur):
            if isinstance(r, dict) and r.get("id") == req_id:
                r["status"] = "succeeded" if ok else "error"
                r["latency_ms"] = latency_ms
                if error_code is not None:
                    r["error_code"] = error_code
                if http_status is not None:
                    r["http_status"] = http_status
                break
        _save(log_file, cur)

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    # TTL configuration: default 7 days if not configured elsewhere.
    TTL_SECONDS = 7 * 24 * 60 * 60

    def _is_stale(row):
        if not isinstance(row, dict):
            return True
        last = _parse_dt(row.get("last_fetched_at"))
        if last is None:
            return True
        # compare in UTC-ish; stored might be naive; treat naive as UTC
        if last.tzinfo is not None:
            last_u = last.astimezone(datetime.timezone.utc).replace(tzinfo=None)
        else:
            last_u = last
        return (now_dt - last_u).total_seconds() > TTL_SECONDS

    def _norm_nonneg_int(v):
        if v is None:
            return None
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v if v >= 0 else None
        if isinstance(v, float):
            if v.is_integer():
                iv = int(v)
                return iv if iv >= 0 else None
            return None
        if isinstance(v, str):
            try:
                iv = int(v)
                return iv if iv >= 0 else None
            except ValueError:
                return None
        return None

    def _safe_str(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v.strip()
            return s if s else None
        return None

    def _safe_array_str(v):
        if v is None:
            return None
        if isinstance(v, list):
            out = []
            for x in v:
                if isinstance(x, str):
                    xs = x.strip()
                    if xs:
                        out.append(xs)
            return out if out else None
        return None

    def _gen_author_stub(aid):
        # Minimal offline-refresh stub that satisfies schema constraints.
        return {
            "id": aid,
            "name": None,
            "affiliations": None,
            "homepage": None,
            "paper_count": None,
            "citation_count": None,
            "h_index": None,
            "external_ids": None,
            "status": "active",
            "last_fetched_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }

    def _offline_refresh(existing_row):
        # No upstream access in this offline server; emulate "refresh" by bumping last_fetched_at
        # and normalizing fields that might violate constraints.
        row = dict(existing_row) if isinstance(existing_row, dict) else _gen_author_stub(author_id)
        row["id"] = author_id
        row["status"] = row.get("status") if row.get("status") in ("active", "tombstoned") else "active"
        row["name"] = _safe_str(row.get("name"))
        row["homepage"] = _safe_str(row.get("homepage"))
        row["affiliations"] = _safe_array_str(row.get("affiliations"))
        row["paper_count"] = _norm_nonneg_int(row.get("paper_count"))
        row["citation_count"] = _norm_nonneg_int(row.get("citation_count"))
        row["h_index"] = _norm_nonneg_int(row.get("h_index"))
        row["external_ids"] = row.get("external_ids") if isinstance(row.get("external_ids"), dict) else None
        row["last_fetched_at"] = now_iso
        if not row.get("created_at"):
            row["created_at"] = now_iso
        row["updated_at"] = now_iso
        return row

    # ---- load cache ----
    authors = _load("authors.json")
    if not isinstance(authors, list):
        authors = []

    idx = None
    for i, r in enumerate(authors):
        if isinstance(r, dict) and r.get("id") == author_id:
            idx = i
            break

    if idx is None:
        # In real service, this would call upstream and might return NOT_FOUND if upstream doesn't know it.
        # In this offline server, create a minimal stub so valid ids still succeed and can be managed.
        new_row = _gen_author_stub(author_id)
        authors.append(new_row)
        _save("authors.json", authors)
        _finalize(True, http_status=200)
        return {"author": new_row, "refreshed": True, "cached": False}

    row = authors[idx]
    if _is_stale(row):
        refreshed = _offline_refresh(row)
        authors[idx] = refreshed
        _save("authors.json", authors)
        _finalize(True, http_status=200)
        return {"author": refreshed, "refreshed": True, "cached": True}

    _finalize(True, http_status=200)
    return {"author": row, "refreshed": False, "cached": True}

def get_semantic_scholar_citations_and_references(paper_id, **_extra):
    import json, os, datetime, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0020000" if __import__("os").path.isdir("./environment_mix/0020000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    if not isinstance(paper_id, str) or paper_id.strip() == "":
        return _err("VALIDATION_ERROR", "paper_id must be a non-empty string")

    papers = _load("papers.json")
    edges = _load("paper_edges.json")

    def _find_paper(pid):
        for p in papers:
            if p.get("id") == pid:
                return p
        return None

    def _new_id(prefix, entropy):
        h = hashlib.sha256(entropy.encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{h}"

    def _normalize_stub_paper(pid):
        # Minimal stub as allowed by business rule; keep within constraints
        return {
            "id": pid,
            "title": None,
            "abstract": None,
            "year": None,
            "venue": None,
            "doi": None,
            "url": None,
            "fields_of_study": None,
            "citation_count": None,
            "reference_count": None,
            "external_ids": None,
            "status": "active",
            "last_fetched_at": None,
            "fetched_etag": None,
            "created_at": now,
            "updated_at": now,
        }

    # Ensure source paper exists; create stub if necessary
    src = _find_paper(paper_id)
    if src is None:
        papers.append(_normalize_stub_paper(paper_id))
        _save("papers.json", papers)
        src = _find_paper(paper_id)

    # Offline "upstream graph refresh":
    # Deterministically create a small set of references and citations based on paper_id.
    # Also enforce "mark edges not returned as removed" for this refresh.
    try:
        h = hashlib.sha256(paper_id.encode("utf-8")).hexdigest()
        # Choose counts 0..5 each
        n_ref = int(h[:2], 16) % 6
        n_cit = int(h[2:4], 16) % 6

        returned_keys = set()

        def _ensure_target(pid):
            if _find_paper(pid) is None:
                papers.append(_normalize_stub_paper(pid))

        # Build targets
        ref_targets = []
        for i in range(n_ref):
            tid = _new_id("paper", f"{paper_id}|ref|{i}")
            if tid == paper_id:
                tid = _new_id("paper", f"{paper_id}|ref|{i}|alt")
            _ensure_target(tid)
            ref_targets.append(tid)

        cit_targets = []
        for i in range(n_cit):
            tid = _new_id("paper", f"{paper_id}|cit|{i}")
            if tid == paper_id:
                tid = _new_id("paper", f"{paper_id}|cit|{i}|alt")
            _ensure_target(tid)
            cit_targets.append(tid)

        _save("papers.json", papers)

        def _upsert_edge(src_id, tgt_id, etype):
            nonlocal edges
            # FK validity
            if _find_paper(src_id) is None or _find_paper(tgt_id) is None:
                raise ValueError("paper FK missing")
            if src_id == tgt_id:
                raise ValueError("source_paper_id must not equal target_paper_id")
            # unique(source, target, type) upsert
            for e in edges:
                if e.get("source_paper_id") == src_id and e.get("target_paper_id") == tgt_id and e.get("edge_type") == etype:
                    # lifecycle transition removed<->active permitted
                    if e.get("status") not in ("active", "removed"):
                        e["status"] = "active"
                    else:
                        e["status"] = "active"
                    e["last_fetched_at"] = now
                    e["updated_at"] = now
                    return e
            eid = _new_id("edge", f"{src_id}|{tgt_id}|{etype}")
            e = {
                "id": eid,
                "source_paper_id": src_id,
                "target_paper_id": tgt_id,
                "edge_type": etype,
                "context": None,
                "is_influential": None,
                "status": "active",
                "last_fetched_at": now,
                "created_at": now,
                "updated_at": now,
            }
            edges.append(e)
            return e

        # Upsert returned edges
        for tid in ref_targets:
            _upsert_edge(paper_id, tid, "reference")
            returned_keys.add((paper_id, tid, "reference"))
        for tid in cit_targets:
            _upsert_edge(paper_id, tid, "citation")
            returned_keys.add((paper_id, tid, "citation"))

        # Mark edges not returned in latest refresh as removed (for this source)
        for e in edges:
            if e.get("source_paper_id") != paper_id:
                continue
            k = (e.get("source_paper_id"), e.get("target_paper_id"), e.get("edge_type"))
            if k not in returned_keys:
                # transition active -> removed allowed; removed -> removed idempotent
                if e.get("status") == "active":
                    e["status"] = "removed"
                    e["updated_at"] = now
                elif e.get("status") == "removed":
                    # still update fetch time? business rule says "mark edges not returned ... as removed"
                    # keep last_fetched_at as-is, but update timestamp to show refresh processed
                    e["updated_at"] = now

        _save("paper_edges.json", edges)

        # Return current set for this paper (both active and removed are in cache; return active only as "current set")
        citations = []
        references = []
        for e in edges:
            if e.get("source_paper_id") != paper_id:
                continue
            if e.get("status") != "active":
                continue
            if e.get("edge_type") == "citation":
                citations.append(e)
            elif e.get("edge_type") == "reference":
                references.append(e)

        # deterministic ordering
        citations.sort(key=lambda x: (str(x.get("target_paper_id") or ""), str(x.get("id") or "")))
        references.sort(key=lambda x: (str(x.get("target_paper_id") or ""), str(x.get("id") or "")))

        return {
            "paper_id": paper_id,
            "citations": citations,
            "references": references,
            "meta": {
                "refreshed_at": now,
                "num_citations": len(citations),
                "num_references": len(references),
            }
        }
    except ValueError as e:
        return _err("VALIDATION_ERROR", "failed to refresh citations/references", detail=str(e))
    except Exception as e:
        return _err("CONFLICT", "internal error", detail=str(e))

