    # ---- request logging + (optional) rate/quota enforcement ----
    def _enforce_and_log(status_code, err_obj=None, extra=None):
        latency_ms = int((time.time() - t0) * 1000)
        # optional request log collection
        reqlog_name = None
        for cand in ("request_logs.json", "usage_logs.json", "audit_logs.json"):
