        u = r.get("updated_at")
        # ISO-8601 Z sorts lexicographically
        return (c if isinstance(c, str) else "", u if isinstance(u, str) else "")

    out.sort(key=_ts_key, reverse=True)

    total = len(out)
    page = out[offset: offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{offset+limit}".encode("utf-8")).decode("utf-8")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
