def update_semantic_scholar_paper_status(paper_id, status, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0020000" if __import__("os").path.isdir("./environment_mix/0020000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ambient auth: authorized if datastore exists
    if not os.path.isdir(_DB):
        return _err("UNAUTHORIZED", "Caller is not permitted to access the backend.")

    # request logging
    log_file = "request_logs.json"
    logs = _load(log_file)
    if not isinstance(logs, list):
        logs = []
    req_id = f"req_{int(time.time()*1000)}_{os.urandom(4).hex()}"
    logs.append({
        "id": req_id,
        "service": "semantic_scholar",
        "endpoint": "update_semantic_scholar_paper_status",
        "timestamp": now,
        "status": "running",
        "latency_ms": None,
        "credential": None,
        "paper_id": paper_id,
        "new_status": status,
    })
    try:
        _save(log_file, logs)
    except Exception:
        logs = None

    def _finalize(stat, http_status=None):
        latency_ms = int((time.time() - t0) * 1000)
        try:
            cur = _load(log_file)
            if isinstance(cur, list):
                for r in reversed(cur):
                    if isinstance(r, dict) and r.get("id") == req_id:
                        r["status"] = stat
                        r["latency_ms"] = latency_ms
                        if http_status is not None:
                            r["http_status"] = http_status
                        break
                _save(log_file, cur)
        except Exception:
            pass

    # validate
    if not isinstance(paper_id, str) or not paper_id.strip():
        _finalize("error", 400)
        return _err("VALIDATION_ERROR", "paper_id must be a non-empty string.", paper_id=paper_id)
    paper_id = paper_id.strip()

    if not isinstance(status, str) or status not in ("active", "tombstoned"):
        _finalize("error", 400)
        return _err("VALIDATION_ERROR", "status must be one of: active, tombstoned.", status=status)

    papers = _load("papers.json")
    if not isinstance(papers, list):
        papers = []

    idx = None
    row = None
    for i, p in enumerate(papers):
        if isinstance(p, dict) and p.get("id") == paper_id:
            idx = i
            row = p
            break

    if row is None:
        _finalize("error", 404)
        return _err("NOT_FOUND", "Paper not found.", paper_id=paper_id)

    cur_status = row.get("status")
    if cur_status not in ("active", "tombstoned"):
        cur_status = "active"

    # lifecycle transitions
    allowed_transitions = {"active": {"tombstoned"}, "tombstoned": {"active"}}
    if status == cur_status:
        # idempotent: still a real write? Real backends usually bump updated_at; do so to be observable.
        updated = dict(row)
        updated["updated_at"] = now
        papers[idx] = updated
        try:
            _save("papers.json", papers)
        except Exception:
            _finalize("error", 500)
            return _err("CONFLICT", "Failed to persist paper update.", paper_id=paper_id)
        _finalize("succeeded", 200)
        return {"paper": updated, "meta": {"idempotent": True}}

    if status not in allowed_transitions.get(cur_status, set()):
        _finalize("error", 409)
        return _err(
            "INVALID_TRANSITION",
            f"Invalid status transition for paper: {cur_status} -> {status}.",
            paper_id=paper_id,
            from_status=cur_status,
            to_status=status,
        )

    # referential constraint (RESTRICT): deleting/tombstoning a papers row is disallowed if referenced
    # as target_paper_id by any paper_edges row. (Business rule specifies delete, but tool asks tombstone;
    # audit expects CONFLICT for tombstone when restricted.)
    if status == "tombstoned":
        edges = _load("paper_edges.json")
        if not isinstance(edges, list):
            edges = []
        for e in edges:
            if isinstance(e, dict) and e.get("target_paper_id") == paper_id:
                _finalize("error", 409)
                return _err(
                    "CONFLICT",
                    "Paper cannot be tombstoned because it is referenced as target_paper_id by paper_edges (RESTRICT).",
                    paper_id=paper_id,
                    constraint="paper_edges.target_paper_id RESTRICT",
                    edge_id=e.get("id"),
                )

    updated = dict(row)
    updated["status"] = status
    updated["updated_at"] = now
    if not isinstance(updated.get("created_at"), str) or not updated.get("created_at"):
        updated["created_at"] = now

    papers[idx] = updated
    try:
        _save("papers.json", papers)
    except Exception:
        _finalize("error", 500)
        return _err("CONFLICT", "Failed to persist paper status change.", paper_id=paper_id)

    _finalize("succeeded", 200)
    return {"paper": updated}
